type ElectionResult = record(winner: str?, count: int, tie: bool)

fn result(votes: list<str>) -> ElectionResult
    let counts = votes |> group_by(v => v) |> keys |> map(v => len(votes |> group_by(v => v) |> keys |> v))
    let winner = counts |> keys |> first
    let count = counts |> get(winner, 0)
    let tie = counts |> keys |> len == 1
    return ElectionResult(winner, count, tie)

