type Vote = record(candidate: str, district: str)

fn district_winner(votes: list<Vote>, district: str) -> str
    let in_district = votes |> filter(v => v.district == district)
    if len(in_district) == 0
        return ""
    let candidates = in_district |> map(v => v.candidate)
    let mut best = first(candidates)
    let mut best_count = len(in_district)
    for c in candidates
        let n = in_district |> count(v => v.candidate == c)
        if n > best_count
            best = c
            best_count = n
    return best

