type Total = record(name: str, hours: dec, overtime: dec)

fn overtime_for(entries: list<Entry>, name: str) -> dec
    let total = entries |> filter(e => e.name == name) |> sum(e => e.hours)
    return max(0.0, total - 40.0)

fn overtime_totals(entries: list<Entry>) -> list<Total>
    let groups = entries |> group_by(e => e.name)
    return keys(groups) |> sort |> map(n => Total(n, sum(get(groups, n, list<Entry>()), e => e.hours), sum(get(groups, n, list<Entry>()), e => e.overtime)))

type Entry = record(name: str, hours: dec, rate: dec)
type Payroll = record(name: str, hours: dec, pay: dec)

fn weekly_pay(entries: list<Entry>, name: str) -> dec
    let total = entries |> filter(e => e.name == name) |> sum(e => e.hours)
    let pay = if total <= 40.0 then total * e => e.rate else (total - 40.0) * e => e.rate * 1.5
    return pay

fn payroll(entries: list<Entry>) -> list<Payroll>
    let groups = entries |> group_by(e => e.name)
    return keys(groups) |> sort |> map(n => Payroll(n, sum(get(groups, n, list<Entry>()), e => e.hours), weekly_pay(entries, n)))

