    let s = stops |> find(x => x.name == name)
    return s.zone

fn trip_fare(stops: list<Stop>, trip: Trip) -> dec
    let from_zone = zone_of(stops, trip.from)
    let to_zone = zone_of(stops, trip.to)
    return max(from_zone, to_zone)

fn stops_between(stops: list<str>, start: str, finish: str) -> int
    if not has(stops, start) or not has(stops, finish)
        return 0
    let mut i = stops.IndexOf(start)
    let mut j = stops.IndexOf(finish)
    if i > j
        return 0
    return j - i + 1

